import {changeHonor} from './diplomacy.js';
export const WORLD_EVENTS=[
 {id:'convoy',name:'Convoy de suministros',text:'Un convoy aliado solicita combustible para cruzar la isla.',cost:{supply:120},reward:{gold:240,wood:180},duration:300},
 {id:'refugees',name:'Supervivientes en la costa',text:'Un grupo aislado necesita alimentos y transporte. Ayudarlo permite incorporar a un especialista.',cost:{gold:160,supply:80},reward:{metal:180},unit:'medic',duration:360},
 {id:'engineers',name:'Brigada de ingenieros',text:'La brigada intercambia materiales por una bonificación temporal de construcción.',cost:{wood:180,metal:60},reward:{gold:100},buff:'construction',duration:300},
 {id:'recon',name:'Exploradores enemigos',text:'Una avanzadilla está reconociendo tus defensas. Puedes enfrentarte a ella para recuperar sus reservas.',cost:{},reward:{gold:350,metal:140},battle:true,duration:300},
 {id:'signal',name:'Señal de otra galaxia',text:'Investiga la transmisión y recibe recursos para preparar la expedición semanal.',cost:{metal:100,supply:100},reward:{gold:280,wood:200},buff:'industry',duration:420},
 {id:'cache',name:'Alijo de campaña',text:'Tus obreros han localizado suministros enterrados. Envía una cuadrilla para recuperarlos.',cost:{wood:80},reward:{gold:220,supply:180,metal:100},duration:300},
 {id:'hospital',name:'Médicos de emergencia',text:'Una caravana médica ofrece tratar a los supervivientes heridos de la guarnición.',cost:{gold:120,supply:60},reward:{},heal:true,duration:300},
 {id:'solar',name:'Actividad solar',text:'Una tormenta afecta a los equipos electrónicos. Refuerza la instalación para mantener activa la industria.',cost:{metal:90},reward:{supply:220},buff:'industry',duration:300}
];
export function initEvents(s){return s.events||=( {version:1,next:s.time+300,index:0,active:null,history:[],pending:{gold:0,wood:0,supply:0,metal:0},buffs:{}} );}
export function eventBonus(s,kind){const e=initEvents(s);return(e.buffs[kind]||0)>s.time?kind==='construction'?.75:1.25:1;}
export function createEvents({storageCap,builders,usedBuilders,makeUnit,population,populationCap,log,startRaid}){
 function tick(s,dt,online=true){if(!online)return;const e=initEvents(s);if(e.active&&s.time>=e.active.ends&&!e.active.battle){e.history.unshift({id:e.active.id,result:'expired',at:s.time});e.history.length=Math.min(30,e.history.length);e.active=null;e.next=s.time+360;}if(!e.active&&!s.battle&&s.time>=e.next){const def=WORLD_EVENTS[e.index++%WORLD_EVENTS.length];e.active={id:def.id,started:s.time,ends:s.time+def.duration,battle:false};log(s,'Evento: '+def.name+'. Consulta Encargos para responder.');}}
 function resolve(s,choice='help'){const e=initEvents(s),a=e.active,def=WORLD_EVENTS.find(v=>v.id===a?.id);if(!a||!def)return{ok:false,message:'Este evento ya no está disponible.'};if(s.battle)return{ok:false,message:'Termina la operación actual.'};if(choice==='dismiss'){if(['refugees','hospital'].includes(def.id))changeHonor(s,-2,'No atendiste a '+def.name+'.');e.history.unshift({id:a.id,result:'dismissed',at:s.time});e.history.length=Math.min(30,e.history.length);e.active=null;e.next=s.time+360;return{ok:true,message:'La base continúa con sus operaciones.'};}if(choice!=='help')return{ok:false,message:'Respuesta no válida.'};if(Object.entries(def.cost).some(([k,v])=>s.resources[k]<v))return{ok:false,message:'Faltan materiales para prestar ayuda.'};if(def.id==='cache'&&usedBuilders(s)>=builders(s))return{ok:false,message:'Necesitas una cuadrilla libre para recuperar el alijo.'};if(def.unit&&population(s)+2>populationCap(s))return{ok:false,message:'Amplía el alojamiento antes de recibir al especialista.'};for(const[k,v]of Object.entries(def.cost))s.resources[k]-=v;if(def.battle){a.battle=true;a.ends=s.time+900;startRaid(s);s.battle.eventId=a.id;s.battle.name='Defensa contra la avanzadilla';return{ok:true,message:'La avanzadilla se aproxima. Protege el centro de mando.'};}for(const[k,v]of Object.entries(def.reward))e.pending[k]+=v;if(def.unit){const u=makeUnit(s,def.unit);s.army.push(u);}if(def.buff)e.buffs[def.buff]=s.time+600;if(def.heal)for(const u of s.army)u.hp=u.maxHp;if(['refugees','hospital'].includes(def.id))changeHonor(s,4,'Auxiliaste a '+def.name+'.');e.history.unshift({id:a.id,result:'helped',at:s.time});e.history.length=Math.min(30,e.history.length);e.active=null;e.next=s.time+420;s.xp+=50;log(s,def.name+': ayuda completada.');claim(s);return{ok:true,message:'Ayuda completada. Las recompensas sin espacio quedan reservadas.'};}
 function battleResult(s,b,victory){if(!b.eventId)return;const e=initEvents(s),def=WORLD_EVENTS.find(v=>v.id===b.eventId);if(!def||e.active?.id!==b.eventId)return;if(victory)for(const[k,v]of Object.entries(def.reward))e.pending[k]+=v;e.history.unshift({id:def.id,result:victory?'victory':'defeat',at:s.time});e.history.length=Math.min(30,e.history.length);e.active=null;e.next=s.time+420;claim(s);}
 function claim(s){const e=initEvents(s),cap=storageCap(s);let n=0;for(const k of Object.keys(e.pending)){const amount=Math.max(0,Math.min(e.pending[k],cap-s.resources[k]));s.resources[k]+=amount;e.pending[k]-=amount;n+=amount;}return{ok:n>0,message:n?'Recompensas recibidas: '+Math.floor(n)+' materiales.':'El almacén está lleno o no quedan recompensas.'};}
 function offline(s,elapsed){const e=s.events;if(!e)return;e.next+=elapsed;if(e.active){e.active.started+=elapsed;e.active.ends+=elapsed;}for(const k of Object.keys(e.buffs))e.buffs[k]+=elapsed;}
 return{tick,resolve,claim,battleResult,offline};
}
